// expr_parity.test.mjs — adversarial JS <-> Python parity of the expression
// engine (SPEC_EXPR E1/E2): docs/js/expr.js + derive.js (the web app) against
// the Python report script generated by docs/js/pyexport.js.
//
// Part 1 (synthetic): a NetCDF-3 file written with scipy (dims a(3), b(4);
// scalars and 1-D/2-D variables in both dim orders; NaN, +-0, +-Inf, huge,
// tiny and subnormal values; units dBm/mW/W/V/Hz/ns...; a variable named like
// a function; names that need quoting). >= 2000 seeded random expressions
// (every operator, unary +/-, ^ / ** chains, every function, SI suffixes,
// quoted names, random whitespace), mutated (mostly invalid) texts, hand-made
// edge cases and deep nesting are evaluated
//   - JS: parseExpr/evalExpr (raw values, broadcast by dim name), exprUnits,
//     and registerDerived on a formula def;
//   - Python: the script's own helpers (parse_expr, eval_on, expr_units,
//     compute_derived) loaded with runpy, as tests/py/probe_helpers.py does,
//     AND the script run end to end with --dump-derived.
// Required: same accept/reject, same names, dims and units, values bit for bit
// for + - * / (and unary), rel 1e-12 otherwise, NaN <-> NaN. Random reduce
// defs with expression windows are compared the same way (rel 1e-9).
// Part 2 (real files: darpa, sidebands, powercal_hdf5): expression windows
// (range, center, outside_within, RBW-proportional widths, k*f harmonics, SI
// offsets, derived centers), formulas and expected errors through the script's
// --dump-derived vs registerDerived (rel 1e-9, NaN <-> NaN, dims, units).
// Every mismatch is shrunk to a minimal repro and printed.
//
// Run:  NCX_PYTHON=/path/to/python node tests/expr_parity.test.mjs
// Without NCX_PYTHON it is skipped. NCX_SEED / NCX_N change the seed and the
// number of random expressions; NCX_KEEP=1 keeps the temp folder.

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import readline from "node:readline";
import { spawn, spawnSync } from "node:child_process";
import { DATA_DIR, PYTHON, loadDataset, dataFile, haveData, moduleUrl, check, skip, summary } from "./node_env.mjs";

if (!process.env.NCX_PYTHON) {
  skip("expr parity", "NCX_PYTHON is not set");
  summary("expr_parity");
  process.exit(0);
}
{
  const r = spawnSync(PYTHON, ["-c", "import numpy, scipy, xarray, matplotlib; print('ok')"], { encoding: "utf8" });
  if (r.status !== 0 || !String(r.stdout).includes("ok")) {
    skip("expr parity", `${PYTHON} lacks numpy/scipy/xarray/matplotlib`);
    summary("expr_parity");
    process.exit(0);
  }
}

const E = await import(moduleUrl("expr.js"));
const D = await import(moduleUrl("derive.js"));
const P = await import(moduleUrl("pyexport.js"));
const X = await import(moduleUrl("explore.js"));
const PJ = await import(moduleUrl("project.js"));

const TMP = fs.mkdtempSync(path.join(os.tmpdir(), "ncx-exprpar-"));
const KEEP = !!process.env.NCX_KEEP;
const SEED = Number(process.env.NCX_SEED || 20261002) >>> 0;
const N_RANDOM = Math.max(2000, Number(process.env.NCX_N || 2400) | 0);
const hasOwn = (o, k) => o != null && Object.prototype.hasOwnProperty.call(o, k);
const prod = (a) => a.reduce((p, q) => p * q, 1);

// ============================================================ Python side
const MK_PY = String.raw`
import sys
import numpy as np
from scipy.io import netcdf_file

nan, inf = float("nan"), float("inf")


def write(path, dims, variables):
    f = netcdf_file(path, "w", version=2)
    for d, n in dims:
        f.createDimension(d, n)
    for name, vdims, data, units, dtype, attrs in variables:
        v = f.createVariable(name, dtype, vdims)
        if dtype == "c":
            v[...] = np.array([[c.encode() for c in row] for row in data], dtype="S1")
        else:
            v[...] = np.asarray(data, dtype=dtype)
        if units is not None:
            v.units = units
        for k, val in attrs.items():
            setattr(v, k, val)
    f.close()


def V(name, vdims, data, units=None, dtype="d", **attrs):
    return (name, vdims, data, units, dtype, attrs)


# main synthetic file: every variable here may appear in random expressions
write(sys.argv[1], [("a", 3), ("b", 4)], [
    V("s0", (), 2.5, "V"), V("sneg", (), -3.0, "V"), V("snan", (), nan, ""),
    V("szero", (), 0.0, "mW"), V("snz", (), -0.0, "W"),
    V("va", ("a",), [1.5, -2.0, 0.0], "dBm"),
    V("vb", ("b",), [1e300, -1e-300, 4.0, nan], "mW"),
    V("b", ("b",), [10.0, 20.0, 30.0, 40.0], "Hz"),
    V("m", ("a", "b"), [[1.0, -0.0, nan, 5e-324], [1e308, -1e308, 2.0, -3.0], [0.0, 7.0, 1e-300, inf]], "dBm"),
    V("n", ("b", "a"), [[0.5, -0.25, 3.0], [1e-10, 1e10, -7.0], [100.0, 0.0, nan], [-1.0, 2.0, 1e-5]], "W"),
    V("t", ("a",), [1.0, 2.0, 3.0], "ns"),
    V("vinf", ("a",), [inf, -inf, 1.0], "dB"),
    V("odd name", ("a",), [0.5, 2.0, -1.0], "dB"),
    V("wl.nm", ("b",), [1550.1, 1550.2, 1550.3, 1550.4], "nm"),
    V("1st", (), 7.0, "W"),
    V("max", ("a",), [3.0, 1.0, 2.0], "dBm"),
    V("ib", ("b",), [1, -2, 3, 0], "", "i"),
    V("big", ("a", "b"), [[1e200, -1e150, 3e300, 1e-200], [-2e250, 5e100, 1e154, -1e155], [7e307, 1.5, -0.5, 1e-310]], ""),
    V("tiny", ("b",), [1e-310, -5e-324, 2.2250738585072014e-308, 0.0], "V"),
])
# edge file: names / units / storage details outside the expression language
write(sys.argv[2], [("a", 3), ("b", 4), ("nchar", 5)], [
    V("pi", (), 3.0, "rad"),
    V("tm", ("b",), [1.0, 2.0, 3.0, 4.0], " minutes"),
    V("label", ("a", "nchar"), ["abcde", "fghij", "klmno"], None, "c"),
    V("x", ("a",), [-10.0, -20.0, -30.0], "dBm"),
    V("bom", ("a",), [-11.0, -21.0, -31.0], "﻿dBm".encode("utf-8")),
    V("us1", ("a",), [-12.0, -22.0, -32.0], "dBm\x1f"),
    V("sc", ("a",), [1, 2, 3], "V", "h", scale_factor=0.5, add_offset=10.0),
    V("t", ("a",), [1.0, 2.0, 3.0], "ns"),
    # a UTF-8 name as netCDF-C writes it (scipy writes names as latin1, so pass
    # the UTF-8 bytes): it needs quoting in an expression
    V("pwr µW".encode("utf-8").decode("latin1"), ("a",), [1.0, 2.0, 4.0], "uW"),
    # a value close to (not equal to) a huge _FillValue
    V("fv", ("a",), [1.0, 1.0000001e36, 2.0], "V", _FillValue=1e36),
])
print("ok")
`;

// JSON-lines server: loads the generated script as a module (main() does not
// run) and evaluates expressions / derived defs with its own helpers
const PROBE_PY = String.raw`
import json
import math
import runpy
import sys
import traceback

import numpy as np

_out = sys.stdout
sys.stdout = sys.stderr            # nothing but replies on the real stdout
ns = runpy.run_path(sys.argv[1], run_name="ncx_parity_probe")
ExprError = ns["ExprError"]
files = {}


def enc(x):
    x = float(x)
    if math.isnan(x):
        return "NaN"
    if math.isinf(x):
        return "Infinity" if x > 0 else "-Infinity"
    return x


def arr(a):
    return [enc(v) for v in np.ravel(np.asarray(a, dtype=float)).tolist()]


def err(e):
    if isinstance(e, ExprError):
        return {"error": str(e), "pos": e.pos}
    return {"error": "%s: %s" % (type(e).__name__, str(e)[:300]), "pos": None, "crash": type(e).__name__}


def clear(f):
    for k in [k for k, v in f._vars.items() if v.derived]:
        del f._vars[k]


def one_expr(f, text):
    r = {}
    try:
        node = ns["parse_expr"](text)
    except Exception as e:
        node = None
        r["parse"] = err(e)
    if node is not None:
        try:
            r["names"] = ns["expr_names"](node)
            r["units"] = ns["expr_units"](node, lambda n: ns["name_units"](f, n))
        except Exception as e:
            r["units_crash"] = err(e)
        try:
            dims = []
            for nm in ns["expr_name_nodes"](node):
                for d in ns["name_dims"](f, nm.value, nm.pos):
                    if d not in dims:
                        dims.append(d)
            shape = tuple(f.size(d) for d in dims)
            vals = np.broadcast_to(ns["eval_on"](f, node, dims), shape)
            r["raw"] = {"dims": dims, "data": arr(vals)}
        except Exception as e:
            r["raw"] = err(e)
    name = "zz_parity"
    clear(f)
    st = ns["compute_derived"]({f.name: f}, [{"name": name, "file": f.name, "kind": "formula", "units": "",
                                              "description": "", "expr": text}], lambda m: None)
    e = st.get((f.name, name))
    if e:
        r["formula"] = {"error": e}
    else:
        v = f.var(name)
        r["formula"] = {"dims": list(v.dims), "units": v.units, "data": arr(v.data)}
    clear(f)
    return r


def dec(v):
    return float(v) if isinstance(v, str) else v


def apply(ops):
    """One operation per entry, on given inputs (each a scalar or an array of
    the shape it has in the real evaluation), through the script's evaluator."""
    Node = ns["Node"]
    res = []
    for o in ops:
        vals = []
        for a in o["args"]:
            if "s" in a:
                vals.append(np.float64(dec(a["s"])))
            else:
                vals.append(np.array([dec(v) for v in a["v"]], dtype=float).reshape(a["shape"]))
        node = Node(o["kind"], o["value"], [Node("name", "x%d" % i, (), -1) for i in range(len(vals))], -1)
        try:
            r = ns["eval_expr"](node, lambda name, pos: vals[int(name[1:])])
            res.append(arr(np.broadcast_to(r, tuple(o["shape"]))))
        except Exception as e:
            res.append({"error": "%s: %s" % (type(e).__name__, e)})
    return res


def derive(f, defs):
    clear(f)
    st = ns["compute_derived"]({f.name: f}, defs, lambda m: None)
    out = {}
    for d in defs:
        e = st.get((f.name, d["name"]), "no status")
        if e:
            out[d["name"]] = {"error": e}
        else:
            v = f.var(d["name"])
            out[d["name"]] = {"dims": list(v.dims), "units": v.units, "data": arr(v.data)}
    clear(f)
    return out


for line in sys.stdin:
    if not line.strip():
        continue
    try:
        req = json.loads(line)
        op = req["op"]
        if op == "open":
            files[req["key"]] = ns["DataFile"](req["key"], req["path"])
            res = {"ok": True}
        elif op == "exprs":
            f = files[req["key"]]
            res = {"results": [one_expr(f, t) for t in req["exprs"]]}
        elif op == "derive":
            res = {"results": derive(files[req["key"]], req["defs"])}
        elif op == "apply":
            res = {"results": apply(req["ops"])}
        else:
            res = {"fatal": "unknown op"}
    except Exception:
        res = {"fatal": traceback.format_exc()}
    _out.write("@@" + json.dumps(res, allow_nan=False) + "\n")
    _out.flush()
`;

function runPy(args, opts = {}) {
  const r = spawnSync(PYTHON, args, { encoding: "utf8", timeout: 600000, maxBuffer: 256 << 20, ...opts });
  return { status: r.status, out: (r.stdout || "") + (r.stderr || ""), error: r.error };
}
// JSON with every non-ASCII UTF-16 unit escaped (lone surrogates survive)
const asciiJSON = (o) => JSON.stringify(o).replace(/[\u007f-￿]/g,
  (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0"));
const dec = (v) => (typeof v === "string" ? Number(v) : v);

class PyProbe {
  constructor(script) {
    this.proc = spawn(PYTHON, [path.join(TMP, "probe.py"), script], { stdio: ["pipe", "pipe", "pipe"],
      env: { ...process.env, PYTHONIOENCODING: "utf-8" } });
    this.queue = [];
    this.stderr = "";
    this.proc.stderr.on("data", (b) => { this.stderr = (this.stderr + b).slice(-4000); });
    this.done = new Promise((res) => this.proc.on("exit", res));
    this.proc.on("exit", (code) => { for (const q of this.queue.splice(0)) q.reject(new Error(`probe exited (${code}): ${this.stderr}`)); });
    readline.createInterface({ input: this.proc.stdout }).on("line", (line) => {
      if (!line.startsWith("@@")) return;
      const q = this.queue.shift();
      if (!q) return;
      const res = JSON.parse(line.slice(2));
      if (res.fatal) q.reject(new Error("probe: " + res.fatal)); else q.resolve(res);
    });
  }
  req(obj) {
    return new Promise((resolve, reject) => {
      this.queue.push({ resolve, reject });
      this.proc.stdin.write(asciiJSON(obj) + "\n");
    });
  }
  close() { this.proc.stdin.end(); return this.done; }   // resolves when python has exited
}

// ============================================================ project / script builders
const WIN = (o = {}) => ({ mode: "none", lo: "", hi: "", lo2: "", hi2: "", center: "", halfwidth: "", halfwidth2: "", ...o });
const RD = (name, file, src, over, xsrc, win, region, stat, db = "auto") => ({ name, file, kind: "reduce", units: "",
  description: "", src, over, xsrc, window: WIN(win), region, stat, db });
const FM = (name, file, expr, units = "") => ({ name, file, kind: "formula", units, description: "", expr });

// one tab per file: a visible trace of a real variable (so a page is drawn)
// plus an invisible trace per derived def (so neededDerived exports them all)
function reportProject(tabsSpec, defs) {
  const tabs = tabsSpec.map(({ file, v, lineDim, xsrc, slices }) => {
    const traces = [X.makeTrace(file, v, lineDim, xsrc, "", slices || {})];
    for (const d of defs) {
      if (d.file !== file) continue;
      traces.push({ ...X.makeTrace(file, d.name, "", "index", "", {}), visible: false });
    }
    return { name: file, plotcfg: { ...X.DEFAULT_PLOTCFG }, traces, markers: [], cur: 0 };
  });
  return JSON.parse(JSON.stringify(PJ.buildProject({ tabs, active: 0, fileOrder: tabsSpec.map((t) => t.file),
    wantedFiles: [], derived: defs })));
}

// ============================================================ JS side
const isNumVar = (v) => !!v && v.isNumeric() && v.data != null && typeof v.data !== "string"
  && typeof v.data.length === "number";
const jsUnitsOf = (ds) => (n) => { const v = hasOwn(ds.vars, n) ? ds.vars[n] : null; return isNumVar(v) ? X.unitsOf(v) : ""; };

// values with dims vd / shape vs broadcast onto (dims, shape) by dim NAME
function bcast(vals, vd, vs, dims, shape) {
  const st = [];
  let acc = 1;
  for (let i = vs.length - 1; i >= 0; i--) { st[i] = acc; acc *= vs[i]; }
  const total = prod(shape), out = new Float64Array(total), idx = new Array(dims.length).fill(0);
  for (let f = 0; f < total; f++) {
    let o = 0;
    dims.forEach((d, j) => { const i = vd.indexOf(d); if (i >= 0) o += idx[j] * st[i]; });
    out[f] = vals[o];
    for (let j = dims.length - 1; j >= 0; j--) { if (++idx[j] < shape[j]) break; idx[j] = 0; }
  }
  return out;
}

// the names of an expression resolved the way derive.js does (numeric var |
// dim | pi), result dims in first-appearance order, and an evalExpr lookup
function jsBind(ds, ast) {
  const refs = E.exprRefs(ast);
  const dims = [], shape = [], binds = new Map();
  for (const { name, pos } of refs) {
    const v = hasOwn(ds.vars, name) ? ds.vars[name] : null;
    let b;
    if (isNumVar(v)) b = { kind: "var", v, dims: v.dims, shape: v.shape };
    else if (hasOwn(ds.dims, name)) b = { kind: "dim", dims: [name], shape: [ds.dims[name]] };
    else if (name === "pi") b = { kind: "const", dims: [], shape: [] };
    else throw new E.ExprError(v ? `'${name}' is not numeric` : `unknown name '${name}'`, pos);
    binds.set(name, b);
    b.dims.forEach((d, i) => { if (!dims.includes(d)) { dims.push(d); shape.push(b.shape[i]); } });
  }
  const total = prod(shape);
  const lookup = (name) => {
    const b = binds.get(name);
    if (!b || b.kind === "const") return undefined;
    if (b.kind === "dim") return bcast(Float64Array.from({ length: b.shape[0] }, (_, i) => i), b.dims, b.shape, dims, shape);
    const vals = X.asFloatArray(b.v.data, b.v.attrs && b.v.attrs.units);
    return b.dims.length ? bcast(vals, b.dims, b.shape, dims, shape) : vals[0];
  };
  return { dims, shape, total, lookup, binds };
}
// the expression the way derive.js reads it, but with RAW results (+-Inf kept)
function jsRaw(ds, ast) {
  const b = jsBind(ds, ast);
  return { dims: b.dims, data: E.evalExpr(ast, b.lookup, b.total) };
}

// Node-by-node re-check of a value mismatch outside + - * /: every operation
// of the expression is applied by the script to JS's own inputs for it (same
// shapes as in the real evaluation: numpy takes other paths for scalars). Exact
// operations must agree bit for bit (sign of zero included), rounded library
// functions (exp, logs, pow ...) to 4 ulp. If every operation agrees, the
// difference is 1-ulp library rounding amplified by an ill-conditioned
// expression (e.g. log(exp(7n))), not an engine mismatch.
const ROUNDED = new Set(["exp", "ln", "log", "log10", "db2lin", "lin2db", "pow", "^"]);
const encNum = (v) => (Object.is(v, -0) ? "-0" : Number.isFinite(v) ? v : String(v));
const fmtNum = (v) => (Object.is(v, -0) ? "-0" : String(v));
function localPlan(ds, text) {
  const ast = E.parseExpr(text);
  const b = jsBind(ds, ast);
  const st = [];
  for (let i = b.shape.length - 1, acc = 1; i >= 0; i--) { st[i] = acc; acc *= b.shape[i]; }
  // a subtree's values in the shape numpy gives it (1 along dims it lacks)
  const asArg = (nd, full) => {
    const keep = new Set(E.exprNames(nd).flatMap((n) => b.binds.get(n).dims));
    if (!keep.size) return { s: encNum(full[0]) };
    const sub = b.dims.map((d, j) => (keep.has(d) ? b.shape[j] : 1));
    const v = [], idx = sub.map(() => 0);
    for (let f = 0, n = prod(sub); f < n; f++) {
      let o = 0;
      for (let j = 0; j < sub.length; j++) o += idx[j] * st[j];
      v.push(encNum(full[o]));
      for (let j = sub.length - 1; j >= 0; j--) { if (++idx[j] < sub[j]) break; idx[j] = 0; }
    }
    return { v, shape: sub };
  };
  const ops = [];
  const walk = (nd) => {
    let kids, kind, value = null;
    if (nd.type === "bin") { kids = [nd.left, nd.right]; kind = "op"; value = nd.op; }
    else if (nd.type === "unary") { kids = [nd.arg]; kind = nd.op === "-" ? "neg" : "plus"; }
    else if (nd.type === "call") { kids = nd.args; kind = "call"; value = nd.fn; }
    else return;
    kids.forEach(walk);
    const args = kids.map((c) => asArg(c, E.evalExpr(c, b.lookup, b.total)));
    ops.push({ js: E.evalExpr(nd, b.lookup, b.total), fn: value || kind, text: printAst(nd).t,
      req: { kind, value, args, shape: b.shape } });
  };
  walk(ast);
  return ops;
}
function localDiff(o, a) {
  if (!Array.isArray(a)) return `${o.text}: python failed (${a && a.error})`;
  for (let i = 0; i < o.js.length; i++) {
    const x = o.js[i], y = dec(a[i]);
    if ((x !== x && y !== y) || Object.is(x, y)) continue;
    if (ROUNDED.has(o.fn) && Number.isFinite(x) && Number.isFinite(y) && x !== 0 && y !== 0 && ulpDist(x, y) <= 4) continue;
    return `operation ${JSON.stringify(o.text)} [${i}]: js ${fmtNum(x)} vs py ${fmtNum(y)} on the same inputs`;
  }
  return "";
}

function jsOne(ds, text) {
  const r = {};
  let ast = null;
  try { ast = E.parseExpr(text); } catch (e) {
    if (!(e instanceof E.ExprError)) r.parse = { error: "CRASH " + e.message, pos: null, crash: true };
    else r.parse = { error: e.message, pos: e.pos };
  }
  if (ast) {
    r.names = E.exprNames(ast);
    r.units = E.exprUnits(ast, jsUnitsOf(ds));
    try { r.raw = jsRaw(ds, ast); } catch (e) {
      r.raw = e instanceof E.ExprError ? { error: e.message, pos: e.pos } : { error: "CRASH " + e.message, pos: null, crash: true };
    }
  }
  const st = D.registerDerived(ds, [FM("zz_parity", ds.filename, text)]).get("zz_parity");
  if (st && st.ok) {
    const v = ds.vars.zz_parity;
    r.formula = { dims: v.dims.slice(), units: String(v.attrs.units), data: Float64Array.from(v.data) };
  } else r.formula = { error: st ? st.error : "no status" };
  D.unregisterDerived(ds);
  r.exact = !!ast && isExactAst(ast);
  return r;
}
// only + - * / and unary +/- (IEEE, must be bit-identical)
function isExactAst(nd) {
  if (nd.type === "call") return false;
  if (nd.type === "bin") return nd.op !== "^" && isExactAst(nd.left) && isExactAst(nd.right);
  if (nd.type === "unary") return isExactAst(nd.arg);
  return true;
}

// ============================================================ comparison
function ulpDist(a, b) {
  const buf = new DataView(new ArrayBuffer(16));
  buf.setFloat64(0, a); buf.setFloat64(8, b);
  const ia = buf.getBigInt64(0), ib = buf.getBigInt64(8);
  const ord = (i) => (i < 0n ? -(i & 0x7fffffffffffffffn) : i);
  const d = ord(ia) - ord(ib);
  return Number(d < 0n ? -d : d);
}
function sameNum(a, b, exact, rel) {
  if (a !== a || b !== b) return a !== a && b !== b;
  if (exact) return Object.is(a, b);
  if (a === b) return true;
  if (!Number.isFinite(a) || !Number.isFinite(b)) return false;
  return Math.abs(a - b) <= rel * Math.max(Math.abs(a), Math.abs(b)) || ulpDist(a, b) <= 2;
}
function firstDiff(a, b, exact, rel) {
  if (!a || !b) return "missing values";
  if (a.length !== b.length) return `length ${a.length} vs ${b.length}`;
  for (let i = 0; i < a.length; i++) {
    const x = a[i], y = dec(b[i]);
    if (!sameNum(x, y, exact, rel)) return `[${i}] js ${Object.is(x, -0) ? "-0" : x} vs py ${Object.is(y, -0) ? "-0" : y}`;
  }
  return "";
}
const crashed = (o) => !!(o && o.crash);
const fmtErr = (o) => (o ? `${o.error}${o.pos !== undefined && o.pos !== null ? ` @${o.pos}` : ""}` : "ok");

// -> [{cat, detail}] (empty: agree)
function compareExpr(js, py) {
  const out = [];
  const add = (cat, detail) => out.push({ cat, detail });
  if (crashed(py.parse) && !js.parse) add("py-crash-parse", `py ${fmtErr(py.parse)}`);
  else if (!!js.parse !== !!py.parse) add("parse-accept", `js ${fmtErr(js.parse)} | py ${fmtErr(py.parse)}`);
  else if (js.parse && js.parse.pos !== py.parse.pos && !crashed(py.parse))
    add("parse-pos", `js ${fmtErr(js.parse)} | py ${fmtErr(py.parse)}`);
  if (!js.parse && !py.parse) {
    if (py.units_crash) add("py-crash-units", fmtErr(py.units_crash));
    else {
      if (JSON.stringify(js.names) !== JSON.stringify(py.names)) add("names", `js ${JSON.stringify(js.names)} | py ${JSON.stringify(py.names)}`);
      if (js.units !== py.units) add("units", `js ${JSON.stringify(js.units)} | py ${JSON.stringify(py.units)}`);
    }
    const jr = js.raw, pr = py.raw;
    if (crashed(pr) && !jr.error) add("py-crash-eval", fmtErr(pr));
    else if (!!jr.error !== !!pr.error) add("eval-accept", `js ${fmtErr(jr.error ? jr : null)} | py ${fmtErr(pr.error ? pr : null)}`);
    else if (jr.error && jr.pos !== pr.pos && !crashed(pr)) add("eval-pos", `js ${fmtErr(jr)} | py ${fmtErr(pr)}`);
    else if (!jr.error) {
      if (JSON.stringify(jr.dims) !== JSON.stringify(pr.dims)) add("raw-dims", `js ${JSON.stringify(jr.dims)} | py ${JSON.stringify(pr.dims)}`);
      else {
        const d = firstDiff(jr.data, pr.data, js.exact, 1e-12);
        if (d) add(js.exact ? "raw-value-exact" : "raw-value", d);
      }
    }
  }
  const jf = js.formula, pf = py.formula;
  if (!!jf.error !== !!pf.error) add("formula-accept", `js ${jf.error || "ok"} | py ${pf.error || "ok"}`);
  else if (!jf.error) {
    if (JSON.stringify(jf.dims) !== JSON.stringify(pf.dims)) add("formula-dims", `js ${JSON.stringify(jf.dims)} | py ${JSON.stringify(pf.dims)}`);
    if (jf.units !== pf.units) add("formula-units", `js ${JSON.stringify(jf.units)} | py ${JSON.stringify(pf.units)}`);
    const d = JSON.stringify(jf.dims) === JSON.stringify(pf.dims) ? firstDiff(jf.data, pf.data, js.exact, 1e-12) : "";
    if (d) add(js.exact ? "formula-value-exact" : "formula-value", d);
  }
  return out;
}

