const PREC = { "+": 1, "-": 1, "*": 2, "/": 2 };
function printAst(nd) {
  switch (nd.type) {
    case "num": return { t: nd.text, p: P_ATOM };
    case "name": return { t: nd.quoted ? `"${nd.name}"` : nd.name, p: P_ATOM };
    case "unary": { const a = printAst(nd.arg); return { t: nd.op + (a.p < P_UN ? `(${a.t})` : a.t), p: P_UN }; }
    case "call": return { t: `${nd.fn}(${nd.args.map((x) => printAst(x).t).join(", ")})`, p: P_ATOM };
    default: {
      const l = printAst(nd.left), r = printAst(nd.right);
      if (nd.op === "^") return { t: `${l.p < P_ATOM ? `(${l.t})` : l.t}^${r.p < P_UN ? `(${r.t})` : r.t}`, p: P_POW };
      const p = PREC[nd.op];
      return { t: `${l.p < p ? `(${l.t})` : l.t} ${nd.op} ${r.p <= p ? `(${r.t})` : r.t}`, p };
    }
  }
}
// every AST with one node replaced by something simpler
function astVariants(root) {
  const out = [];
  const LEAVES = ["1", "0", "2", "-0"].map((t) => (t === "-0" ? { type: "unary", op: "-", arg: { type: "num", text: "0" } }
    : { type: "num", text: t }));
  const walk = (nd, rebuild) => {
    const repl = [];
    if (nd.type === "unary") repl.push(nd.arg);
    if (nd.type === "bin") repl.push(nd.left, nd.right);
    if (nd.type === "call") {
      repl.push(...nd.args);
      if (nd.args.length > 1) nd.args.forEach((_, i) => repl.push({ ...nd, args: nd.args.filter((__, j) => j !== i) }));
    }
    if (nd.type !== "num") repl.push(...LEAVES);
    for (const r of repl) out.push(rebuild(r));
    if (nd.type === "unary") walk(nd.arg, (x) => rebuild({ ...nd, arg: x }));
    if (nd.type === "bin") {
      walk(nd.left, (x) => rebuild({ ...nd, left: x }));
      walk(nd.right, (x) => rebuild({ ...nd, right: x }));
    }
    if (nd.type === "call") nd.args.forEach((a, i) => walk(a, (x) => rebuild({ ...nd, args: nd.args.map((y, j) => (j === i ? x : y)) })));
  };
  walk(root, (x) => x);
  return out.map((a) => printAst(a).t);
}
const weight = (t) => t.replace(/[ \t\r\n]/g, "").length + (t.length - t.replace(/[ \t\r\n]/g, "").length) * 0.01;
function candidates(text) {
  const c = new Set();
  try { for (const v of astVariants(E.parseExpr(text))) c.add(v); } catch (e) { /* text-level only */ }
  try { c.add(printAst(E.parseExpr(text)).t); } catch (e) { /* not parseable */ }
  if (text.length <= 400) {
    for (let i = 0; i < text.length; i++) c.add(text.slice(0, i) + text.slice(i + 1));
    for (let i = 0; i < text.length; i++) for (const L of [2, 3, 5, 8]) c.add(text.slice(0, i) + text.slice(i + L));
  } else {
    c.add(text.slice(1, -1)); c.add(text.slice(2, -2)); c.add(text.slice(10, -10)); c.add(text.slice(50, -50));
  }
  c.delete(text);
  return [...c].filter((t) => weight(t) < weight(text)).sort((a, b) => weight(a) - weight(b)).slice(0, 600);
}

