const VALUE_CATS = new Set(["raw-value", "formula-value"]);
let noise = 0;
const noiseEx = [], noiseTexts = new Set();
async function evalBoth(which, texts) {
  const key = which === "syn" ? "syn.nc" : "edge.nc";
  const res = (await py.req({ op: "exprs", key, exprs: texts })).results;
  const out = texts.map((t, i) => {
    const js = jsOne(DS[which], t);
    return { text: t, js, py: res[i], diffs: compareExpr(js, res[i]) };
  });
  // value mismatches outside + - * /: re-check operation by operation
  const need = out.filter((r) => !r.js.exact && r.diffs.some((d) => VALUE_CATS.has(d.cat)));
  if (need.length) {
    const plans = need.map((r) => { try { return localPlan(DS[which], r.text); } catch (e) { return null; } });
    const reqs = plans.flatMap((p) => (p ? p.map((o) => o.req) : []));
    const ans = reqs.length ? (await py.req({ op: "apply", ops: reqs })).results : [];
    let k = 0;
    need.forEach((r, i) => {
      if (!plans[i]) return;
      let bad = "";
      for (const o of plans[i]) { const a = ans[k++]; if (!bad) bad = localDiff(o, a); }
      if (bad) {
        for (const d of r.diffs) if (VALUE_CATS.has(d.cat)) d.detail += `; ${bad}`;
      } else {
        noise++;
        noiseTexts.add(r.text);
        if (noiseEx.length < 3) noiseEx.push(`${JSON.stringify(r.text)}: ${r.diffs.filter((d) => VALUE_CATS.has(d.cat)).map((d) => d.detail).join("; ")}`);
        r.diffs = r.diffs.filter((d) => !VALUE_CATS.has(d.cat));
      }
    });
  }
  return out;
}

async function shrink(which, text, cat) {
  let cur = text;
  for (let round = 0; round < 60; round++) {
    const cands = candidates(cur);
    if (!cands.length) break;
    let next = null;
    for (let i = 0; i < cands.length && !next; i += 150) {
      const rs = await evalBoth(which, cands.slice(i, i + 150));
      const hit = rs.find((r) => r.diffs.some((d) => d.cat === cat));
      if (hit) next = hit.text;
    }
    if (!next) break;
    cur = next;
  }
  const [r] = await evalBoth(which, [cur]);
  return { text: cur, detail: (r.diffs.find((d) => d.cat === cat) || {}).detail };
}

// ---- part 1a: random + mutated + hand-made expressions on the synthetic file
const texts = [];
for (let i = 0; i < N_RANDOM; i++) texts.push(gen(1 + ri(5)).t);
const nValid = texts.length;
for (let i = 0; i < Math.round(N_RANDOM / 4); i++) texts.push(mutate(pick(texts.slice(0, nValid))));
texts.push(...HAND);
const results = [];
for (let i = 0; i < texts.length; i += 500) results.push(...await evalBoth("syn", texts.slice(i, i + 500)));
const jsAccepted = results.filter((r) => !r.js.parse).length;
const cover = { ops: new Set(), fns: new Set(), si: new Set(), quoted: 0, pow2: 0, neg: 0 };
for (const r of results) {
  try {
    const ast = E.parseExpr(r.text);
    const w = (nd) => {
      if (nd.type === "bin") { cover.ops.add(nd.op); if (nd.op === "^" && nd.right.type === "bin" && nd.right.op === "^") cover.pow2++; w(nd.left); w(nd.right); }
      else if (nd.type === "unary") { cover.ops.add("u" + nd.op); if (nd.op === "-" && nd.arg.type === "bin" && nd.arg.op === "^") cover.neg++; w(nd.arg); }
      else if (nd.type === "call") { cover.fns.add(nd.fn); nd.args.forEach(w); }
      else if (nd.type === "num") { const s = nd.text.slice(-1); if (hasOwn(E.SI, s)) cover.si.add(s); }
      else if (nd.type === "name" && nd.quoted) cover.quoted++;
    };
    w(ast);
  } catch (e) { /* invalid */ }
}
console.log(`part 1a: ${texts.length} expressions (${nValid} random, ${texts.length - nValid - HAND.length} mutated, `
  + `${HAND.length} hand-made), ${jsAccepted} parse in JS; ops ${[...cover.ops].sort().join(" ")}; `
  + `functions ${cover.fns.size}/${FN.length}; SI ${[...cover.si].join("")}; quoted ${cover.quoted}; a^b^c ${cover.pow2}; -a^b ${cover.neg}`);
check("part 1a: >= 2000 random expressions", nValid >= 2000, nValid);
check("part 1a: every operator covered", ["+", "-", "*", "/", "^", "u-", "u+"].every((o) => cover.ops.has(o)), [...cover.ops]);
check("part 1a: every function covered", cover.fns.size === FN.length, [...cover.fns]);
check("part 1a: every SI suffix covered", Object.keys(E.SI).every((s) => cover.si.has(s)), [...cover.si]);
check("part 1a: python answered every expression", results.every((r) => r.py && r.py.formula), "");

// group by category; shrink the smallest example of each
async function report(part, which, rs) {
  const byCat = new Map();
  for (const r of rs) for (const d of r.diffs) {
    if (!byCat.has(d.cat)) byCat.set(d.cat, []);
    byCat.get(d.cat).push({ text: r.text, detail: d.detail });
  }
  for (const [cat, list] of byCat) {
    list.sort((a, b) => weight(a.text) - weight(b.text));
    // a few examples with DIFFERENT messages (digits ignored), smallest first
    const seen = new Set(), ex = [];
    for (const e of list) {
      const sig = String(e.detail).replace(/[-\d.e+]+|Infinity/g, "#");
      if (!seen.has(sig) && ex.length < 6) { seen.add(sig); ex.push(e); }
    }
    const min = await shrink(which, ex[0].text, cat);
    findings.push({ part, cat, count: list.length, text: min.text, detail: min.detail, examples: ex });
    console.log(`MISMATCH ${part} [${cat}] x${list.length}  minimal: ${JSON.stringify(min.text)}  -> ${min.detail}`);
    for (const e of ex) console.log(`    e.g. ${JSON.stringify(e.text).slice(0, 160)}  -> ${String(e.detail).split("\n")[0]}`);
    check(`${part}: no '${cat}' mismatch`, false, `${list.length} case(s), minimal ${JSON.stringify(min.text)}: ${min.detail}`);
  }
  if (!byCat.size) check(`${part}: JS and Python agree on all ${rs.length} expressions`, true);
}
console.log(`part 1a: ${noise} value difference(s) outside + - * / traced to 1-4 ulp library rounding `
  + `(every operation agrees on the same inputs)${noiseEx.map((e) => "\n    " + e).join("")}`);
await report("part 1a (syn)", "syn", results);

