// ---- part 1c: end-to-end: the generated script with --dump-derived (all formulas)
{
  const fdefs = texts.map((t, i) => FM(`f${i}`, "syn.nc", t));
  const proj = reportProject([{ file: "syn.nc", v: "m", lineDim: "b", xsrc: "coord" }], fdefs);
  const script = P.buildReportScript(proj, { generatedAt: "2026-10-02T00:00:00.000Z" });
  const sp1 = path.join(TMP, "e2e_syn.py"), dj = path.join(TMP, "e2e_syn.json");
  fs.writeFileSync(sp1, script, "utf8");
  const r = runPy([sp1, "--data-dir", TMP, "--out", path.join(TMP, "e2e_syn.pdf"), "--dump-derived", dj]);
  fs.writeFileSync(path.join(TMP, "e2e_syn.out.txt"), r.out);
  if (check("part 1c: script ran (exit 0)", r.status === 0, r.out.slice(-2000))) {
    const dump = JSON.parse(fs.readFileSync(dj, "utf8"))["syn.nc"] || {};
    const bad = [];
    results.forEach((res, i) => {
      const jf = res.js.formula, pv = dump[`f${i}`];
      let why = "";
      if (!!jf.error !== !pv) why = `accept: js ${jf.error || "ok"} | script ${pv ? "computed" : "not computed"}`;
      else if (pv) {
        if (JSON.stringify(jf.dims) !== JSON.stringify(pv.dims)) why = `dims js ${JSON.stringify(jf.dims)} | script ${JSON.stringify(pv.dims)}`;
        else if (jf.units !== pv.units) why = `units js ${JSON.stringify(jf.units)} | script ${JSON.stringify(pv.units)}`;
        else if (!noiseTexts.has(res.text)) why = firstDiff(jf.data, pv.data.map((v) => (v === null ? NaN : v)), res.js.exact, 1e-12);
      }
      if (why) bad.push({ text: res.text, why });
    });
    bad.sort((a, b) => weight(a.text) - weight(b.text));
    for (const b of bad.slice(0, 8)) console.log(`MISMATCH part 1c (--dump-derived) ${JSON.stringify(b.text).slice(0, 160)} -> ${b.why}`);
    if (bad.length) findings.push({ part: "part 1c", cat: "dump-derived", count: bad.length, text: bad[0].text, detail: bad[0].why });
    check(`part 1c: --dump-derived == registerDerived for ${results.length} formulas`, !bad.length,
      bad.length ? `${bad.length} differ, e.g. ${JSON.stringify(bad[0].text)}: ${bad[0].why}` : "");
  }
}

// ---- part 1d: random reduce defs with expression windows (synthetic file)
{
  const WNUM = ["0", "1", "1.5", "2", "3", "10", "15", "25", "35", "40", "1550.15", "1550.3", "5", "0.5", "-1",
    "1e3", "20m", "0.02k", "1e-9", "0"];
  const WNAME = ["va", "a", "s0", "sneg", "snan", "szero", "t", "vinf", '"odd name"', '"1st"', "max", "pi", "snz"];
  const wexpr = (d) => {
    const r = rnd();
    if (d <= 0 || r < 0.35) return chance(0.03) ? pick(["b", "m", "nope", "1 +", ""]) : (chance(0.55) ? pick(WNUM) : pick(WNAME));
    if (r < 0.75) return `${wexpr(d - 1)} ${pick(["+", "-", "*", "/"])} ${wexpr(d - 1)}`;
    if (r < 0.85) return `-(${wexpr(d - 1)})`;
    if (r < 0.92) return `${pick(["abs", "floor", "round", "sqrt", "ln", "db2lin"])}(${wexpr(d - 1)})`;
    return `${pick(["min", "max", "pow"])}(${wexpr(d - 1)}, ${wexpr(d - 1)})`;
  };
  const SRC = [["m", "b"], ["n", "b"], ["m", "a"], ["n", "a"], ["vb", "b"], ["big", "b"]];
  const XS = ["index", "coord", "var:wl.nm", "var:ib", "var:b", "var:vb", "var:tiny"];
  const defs = [];
  for (let i = 0; i < 600; i++) {
    const [src, over] = pick(SRC), mode = pick(["none", "range", "range", "center", "center"]);
    const region = mode === "none" ? "inside" : pick(["inside", "outside", "outside_within"]);
    const w = { mode };
    if (mode === "range") { w.lo = wexpr(2); w.hi = wexpr(2); if (region === "outside_within" || chance(0.2)) { w.lo2 = wexpr(2); w.hi2 = wexpr(2); } }
    if (mode === "center") { w.center = wexpr(2); w.halfwidth = wexpr(2); if (region === "outside_within" || chance(0.2)) w.halfwidth2 = wexpr(2); }
    const xs = over === "b" ? pick(XS) : pick(["index", "coord"]);
    defs.push(RD(`w${i}`, "syn.nc", src, over, xs, w, region,
      pick(["max", "min", "mean", "median", "std", "sum", "integral", "count", "argmax_x", "argmin_x"]), pick(["auto", "yes", "no"])));
  }
  const pyRes = (await py.req({ op: "derive", key: "syn.nc", defs })).results;
  const jsRes = new Map();
  for (let i = 0; i < defs.length; i += 200) {
    const chunk = defs.slice(i, i + 200);
    const st = D.registerDerived(dsSyn, chunk);
    for (const d of chunk) {
      const s = st.get(d.name), v = dsSyn.vars[d.name];
      jsRes.set(d.name, s && s.ok ? { dims: v.dims.slice(), units: String(v.attrs.units), data: Float64Array.from(v.data) }
        : { error: s ? s.error : "no status" });
    }
  }
  D.unregisterDerived(dsSyn);
  const bad = [];
  let ok = 0;
  for (const d of defs) {
    const j = jsRes.get(d.name), p = pyRes[d.name];
    let why = "";
    if (!!j.error !== !!p.error) why = `accept: js ${j.error || "ok"} | py ${p.error || "ok"}`;
    else if (!j.error) {
      ok++;
      if (JSON.stringify(j.dims) !== JSON.stringify(p.dims)) why = `dims js ${JSON.stringify(j.dims)} | py ${JSON.stringify(p.dims)}`;
      else if (j.units !== p.units) why = `units js ${JSON.stringify(j.units)} | py ${JSON.stringify(p.units)}`;
      else why = firstDiff(j.data, p.data, false, 1e-9);
    }
    if (why) bad.push({ d, why });
  }
  console.log(`part 1d: ${defs.length} random reduce defs, ${ok} computed by both, ${bad.length} mismatches`);
  for (const b of bad.slice(0, 10)) console.log(`MISMATCH part 1d ${JSON.stringify({ src: b.d.src, over: b.d.over, xsrc: b.d.xsrc, window: b.d.window, region: b.d.region, stat: b.d.stat, db: b.d.db })} -> ${b.why}`);
  if (bad.length) findings.push({ part: "part 1d", cat: "window", count: bad.length, text: JSON.stringify(bad[0].d), detail: bad[0].why });
  check("part 1d: random expression windows agree (rel 1e-9)", !bad.length, bad.length ? `${bad.length} differ` : "");
  check("part 1d: enough windows computed by both", ok >= 200, ok);
}

// ---- part 1e: def-level cases (names that collide with dims / variables / pi /
// functions, failed dependencies, cycles, chains, unused or odd window fields)
{
  const S = "syn.nc";
  const w0 = WIN();
  const CASES = [
    ["def named like a dimension, used by another def", [FM("a", S, "1"), FM("ua", S, "a + 1")]],
    ["def named like a real variable, used by another def", [FM("m", S, "1"), FM("um", S, "m*2")]],
    ["failed def named pi, used by another def", [FM("pi", S, "1 +"), FM("upi", S, "pi*2")]],
    ["def named pi", [FM("pi", S, "3"), FM("upi2", S, "pi*2")]],
    ["def named like a function", [FM("ceil", S, "va*2"), FM("uc", S, "ceil + ceil(va)")]],
    ["self reference", [FM("selfref", S, "selfref + 1")]],
    ["cycle", [FM("c1", S, "c2 + 1"), FM("c2", S, "c1 + 1"), FM("c3", S, "c1 * 0 + 5")]],
    ["duplicate name", [FM("dup", S, "1"), FM("dup", S, "2"), FM("udup", S, "dup*3")]],
    ["quoted def name", [FM("my snr", S, "va - 1"), FM("use", S, '"my snr" * 2')]],
    ["window centered on a formula", [FM("cen", S, "a*10 + 15"),
      RD("pk", S, "m", "b", "coord", { mode: "center", center: "cen", halfwidth: "6" }, "inside", "max"), FM("pkd", S, "pk - va")]],
    ["unused window fields hold junk", [RD("uw", S, "m", "b", "index", { mode: "center", center: "1", halfwidth: "1",
      lo: "nope +", hi: "c9", halfwidth2: "zz" }, "inside", "max")]],
    ["cycle only through an unused window field", [RD("cy1", S, "m", "b", "index", { mode: "center", center: "1",
      halfwidth: "1", lo: "cy2", halfwidth2: "cy2" }, "inside", "max"), FM("cy2", S, "cy1 + 1")]],
    ["window uses a failed def", [FM("bad", S, "1 +"), RD("wb", S, "m", "b", "index", { mode: "center", center: "bad", halfwidth: "1" }, "inside", "max")]],
    ["numbers in a new-format window", [{ ...RD("nw", S, "m", "b", "index", {}, "inside", "max"), window: { ...w0, mode: "range", lo: 1, hi: 2.5 } }]],
    ["var: center under mode center", [{ ...RD("vc", S, "m", "b", "index", {}, "inside", "max"),
      window: { ...w0, mode: "center", center: "var:va", halfwidth: "1" } }]],
    ["legacy relative window", [{ ...RD("lr", S, "m", "b", "coord", {}, "inside", "max"),
      window: { mode: "relative", lo: null, hi: null, lo2: null, hi2: null, center: "var:va", k: 2, offset: 0.5, halfwidth: -1, halfwidth2: null } }]],
    ["window over dims the result lacks", [RD("wd", S, "m", "b", "index", { mode: "center", center: "b", halfwidth: "1" }, "inside", "max")]],
    ["time units through a derived var", [FM("tt", S, "t"), FM("tt2", S, "tt*1")]],
    ["0-D formula", [FM("k0", S, "2*pi"), FM("k1", S, "k0 + va")]],
  ];
  const py2 = new PyProbe(helperScript);
  await py2.req({ op: "open", key: S, path: synPath });
  for (const [id, defs] of CASES) {
    const pr = (await py2.req({ op: "derive", key: S, defs })).results;
    const st = D.registerDerived(dsSyn, defs);
    const names = [...new Set(defs.map((d) => d.name))];
    const diffs = [];
    for (const n of names) {
      const s = st.get(n), p = pr[n], v = dsSyn.vars[n];
      if (!!(s && s.ok) === !!p.error) { diffs.push(`'${n}': js ${s && s.ok ? "ok" : (s ? s.error : "no status")} | py ${p.error || "ok"}`); continue; }
      if (p.error) continue;
      if (JSON.stringify(v.dims) !== JSON.stringify(p.dims)) diffs.push(`'${n}' dims js ${JSON.stringify(v.dims)} | py ${JSON.stringify(p.dims)}`);
      else if (String(v.attrs.units) !== p.units) diffs.push(`'${n}' units js ${JSON.stringify(v.attrs.units)} | py ${JSON.stringify(p.units)}`);
      else { const d = firstDiff(Array.from(v.data), p.data, false, 1e-9); if (d) diffs.push(`'${n}' values ${d}`); }
    }
    D.unregisterDerived(dsSyn);
    if (diffs.length) {
      console.log(`MISMATCH part 1e [${id}] ${JSON.stringify(defs.map((d) => (d.kind === "formula" ? { [d.name]: d.expr } : { [d.name]: d.window })))} -> ${diffs.join("; ")}`);
      findings.push({ part: "part 1e", cat: id, text: JSON.stringify(defs.map((d) => d.name)), detail: diffs.join("; ") });
    }
    check(`part 1e: ${id}`, !diffs.length, diffs.join("; "));
  }
  await py2.close();
}
await py.close();

